function tasks(){$('#view').innerHTML='<div class="card"><div class="toolbar"><div><h2>Задачи отряда</h2><span class="muted">Собрать, налутать, скрафтить или доставить на базу.</span></div><button class="primary" onclick="newTask()">+ СОЗДАТЬ ЗАДАЧУ</button></div><div class="list">'+(db.tasks.length?['В процессе','Просрочено','Выполнено'].map((label)=>{let items=db.tasks.filter(t=>taskStatusLabel(t)===label);return items.length?'<div class="task-group-title '+(label==='Просрочено'?'task-group-late':'')+'">'+label+' <span>'+items.length+'</span></div>'+items.map(taskCard).join(''):''}).join(''):'<div class="empty">Задач пока нет</div>')+'</div></div>'}
function participantWord(n){n=Number(n)||0;let m=n%100,a=n%10;return (m>=11&&m<=14)?'участников':a===1?'участник':(a>=2&&a<=4)?'участника':'участников'}
function formatPlanDate(d){if(!d)return'';let p=d.split('-');return p.length===3?p[2]+'.'+p[1]+'.'+p[0]:d}
function ops(){$('#view').innerHTML='<div class="card"><div class="toolbar"><div><h2>План на рейд</h2><span class="muted">Создать общий план отряда на выбранную дату и время.</span></div><button class="primary" onclick="newOp()">+ СОЗДАТЬ ПЛАН</button></div><div class="list">'+(db.ops.length?db.ops.map(o=>{let p=Array.isArray(o.participants)?o.participants:[];return '<div class="item raiditem raidclick" onclick="viewOp('+o.id+')"><div class="itemtop"><div style="flex:1"><h3>'+esc(o.title)+'</h3><div class="muted">'+(o.date?formatPlanDate(o.date)+' · ':'')+esc(o.time)+(o.note?' · '+esc(o.note):'')+'</div></div><span class="badge">'+p.length+' '+participantWord(p.length)+'</span></div><div class="raid-list-roster"><small class="muted">Участники:</small><div class="raid-roster">'+db.members.map(m=>'<span class="raid-roster-name '+(p.includes(m[0])?'is-in':'is-out')+'">'+esc(m[0])+'</span>').join('<span class="raid-comma">, </span>')+'</div></div><div class="actions"><button class="raid-participation '+(p.includes(db.profile.nick)?'leave':'join')+'" onclick="event.stopPropagation();toggleRaid('+o.id+')">'+(p.includes(db.profile.nick)?'Не участвую':'Участвую')+'</button><button onclick="event.stopPropagation();editOp('+o.id+')">Редактировать</button><button onclick="event.stopPropagation();deleteOp('+o.id+')">Удалить</button></div></div>'}).join(''):'<div class="empty">Планов пока нет</div>')+'</div></div>'}
let photoScrollY=0;
function closeRaidPhoto(){
 const d=document.getElementById('photoViewer');if(d)d.remove();
 document.documentElement.style.overflow='';
 document.body.style.overflow='';
 document.body.style.position='';
 document.body.style.top='';
 document.body.style.width='';
 window.scrollTo(0,photoScrollY);
}
function openRaidPhoto(url){
 closeRaidPhoto();
 photoScrollY=window.scrollY||window.pageYOffset||0;
 const d=document.createElement('div');d.id='photoViewer';
 d.setAttribute('style','position:fixed!important;inset:0!important;z-index:2147483647!important;background:#000!important;overflow:hidden!important;touch-action:none!important;');
 const img=document.createElement('img');img.src=url;img.alt='Фото';
 img.setAttribute('style','position:absolute!important;left:50%!important;top:50%!important;display:block!important;width:auto!important;height:auto!important;max-width:calc(100vw - 24px)!important;max-height:calc(100dvh - 24px)!important;object-fit:contain!important;transform:translate(-50%,-50%) translate(0px,0px) scale(1);transform-origin:center center!important;user-select:none!important;-webkit-user-drag:none!important;touch-action:none!important;');
 d.appendChild(img);document.body.appendChild(d);
 let scale=1,startScale=1,startDist=0,moved=false,tx=0,ty=0,startTx=0,startTy=0,startMidX=0,startMidY=0,downX=0,downY=0;
 const apply=()=>{img.style.transform='translate(-50%,-50%) translate('+tx+'px,'+ty+'px) scale('+scale+')'};
 const dist=t=>Math.hypot(t[0].clientX-t[1].clientX,t[0].clientY-t[1].clientY);
 const mid=t=>({x:(t[0].clientX+t[1].clientX)/2,y:(t[0].clientY+t[1].clientY)/2});
 d.addEventListener('touchstart',e=>{if(e.touches.length===2){e.preventDefault();startDist=dist(e.touches);startScale=scale;startTx=tx;startTy=ty;let m=mid(e.touches);startMidX=m.x;startMidY=m.y;moved=true}else if(e.touches.length===1){downX=e.touches[0].clientX;downY=e.touches[0].clientY;startTx=tx;startTy=ty;moved=false}},{passive:false});
 d.addEventListener('touchmove',e=>{if(e.touches.length===2&&startDist){e.preventDefault();let m=mid(e.touches),ns=Math.max(1,Math.min(5,startScale*dist(e.touches)/startDist)),ratio=ns/startScale;tx=m.x-innerWidth/2-(startMidX-innerWidth/2-startTx)*ratio;ty=m.y-innerHeight/2-(startMidY-innerHeight/2-startTy)*ratio;scale=ns;if(scale<=1.001){scale=1;tx=0;ty=0}apply();moved=true}else if(e.touches.length===1&&scale>1){e.preventDefault();let dx=e.touches[0].clientX-downX,dy=e.touches[0].clientY-downY;if(Math.abs(dx)>3||Math.abs(dy)>3)moved=true;tx=startTx+dx;ty=startTy+dy;apply()}},{passive:false});
 d.addEventListener('touchend',e=>{if(!e.touches.length&&!moved)closeRaidPhoto();if(!e.touches.length){startDist=0;if(scale<=1.01){scale=1;tx=0;ty=0;apply()}}},{passive:false});
 d.addEventListener('click',()=>{if(!('ontouchstart' in window))closeRaidPhoto()});
}
function viewOp(id){let o=db.ops.find(x=>x.id===id);if(!o)return;modal('<h2>'+esc(o.title)+'</h2><p>'+(o.date?formatPlanDate(o.date)+' · ':'')+esc(o.time)+'</p>'+(o.sector?'<p>Сектор: '+esc(o.sector)+'</p>':'')+(o.walls?'<p>Стены: '+o.walls+'</p>':'')+(o.transport?'<p>Транспорт: '+esc(o.transport)+'</p>':'')+(o.loadout?'<p>Что взять: '+esc(o.loadout)+'</p>':'')+(o.rally_point?'<p>Точка сбора: '+esc(o.rally_point)+'</p>':'')+(o.note?'<p>Комментарий: '+esc(o.note)+'</p>':'')+(o.images&&o.images.length?'<div class="raidphotos">'+o.images.map(u=>'<img src="'+esc(u)+'" alt="Фото для рейда" onclick="openRaidPhoto(\''+esc(u)+'\')" style="cursor:zoom-in">').join('')+'</div>':'')+'<div class="raid-detail-people"><span>УЧАСТНИКИ</span><div class="raid-roster">'+db.members.map(m=>'<span class="raid-roster-name '+((o.participants||[]).includes(m[0])?'is-in':'is-out')+'">'+esc(m[0])+'</span>').join('<span class="raid-comma">, </span>')+'</div></div><div class="dialogfoot raid-detail-actions"><button class="raid-join raid-participation '+((o.participants||[]).includes(db.profile.nick)?'leave':'join')+'" onclick="toggleRaid('+o.id+',true)">'+((o.participants||[]).includes(db.profile.nick)?'Не участвую':'Участвую')+'</button>'+((o.creator===db.profile.nick||db.profile.access==='admin')?'<button onclick="editOp('+o.id+')">Редактировать</button>':'')+((o.creator===db.profile.nick||db.profile.access==='admin')?'<button class="danger" onclick="deleteOp('+o.id+');closeModal()">Удалить</button>':'')+'<button class="ghost" onclick="closeModal()">Закрыть</button></div>')}
function members(){let admin=db.profile.access==='admin'||db.profile.nick==='k1t0';$('#view').innerHTML='<div class="card"><div class="toolbar"><div><h2>Состав FURY</h2><span class="muted">Ник, роль, время захода и статус на сегодня.</span></div>'+(admin?'<button class="ghost" onclick="changeInviteCode()">СМЕНИТЬ КОД ВСТУПЛЕНИЯ</button>':'')+'</div><div class="list">'+db.members.map(m=>'<div class="item"><div class="itemtop"><div><h3>'+esc(m[0])+(m[0]===db.profile.nick&&admin?' <span class="badge work">АДМИН</span>':'')+'</h3><span class="muted">'+esc(m[1])+'</span></div><div class="member-actions-row" style="display:flex!important;flex-direction:row!important;flex-wrap:nowrap!important;align-items:center!important;justify-content:flex-end!important;gap:8px!important">'+(admin&&m[0]!==db.profile.nick?'<button onclick="editMemberNick(\''+esc(m[0]).replace(/'/g,"\\'")+'\')">Изменить ник</button><button class="danger" onclick="kickMemberByNick(\''+esc(m[0]).replace(/'/g,"\\'")+'\')">Выгнать</button>':'')+'</div></div></div>').join('')+'</div></div>'}
function editMemberNick(nick){if(db.profile.access!=='admin'&&db.profile.nick!=='k1t0')return;modal('<h2>Изменить ник</h2><form class="form" onsubmit="saveMemberNick(event,\''+esc(nick).replace(/'/g,"\\'")+'\')"><span class="muted">Текущий ник: '+esc(nick)+'</span><input name="nick" required maxlength="40" value="'+esc(nick)+'" placeholder="Новый ник"><div class="dialogfoot"><button type="button" class="ghost" onclick="closeModal()">Отмена</button><button class="primary">Сохранить</button></div></form>')}
async function saveMemberNick(e,oldNick){e.preventDefault();if(!sb||!onlineMember)return;let newNick=String(new FormData(e.target).get('nick')||'').trim();if(!newNick)return;let {data:m,error}=await sb.from('members').select('id').eq('squad_id',onlineMember.squad_id).eq('nick',oldNick).single();if(error||!m){toast('Участник не найден');return}let r=await sb.rpc('admin_rename_member',{p_member_id:m.id,p_new_nick:newNick});if(r.error){toast(r.error.message.includes('exists')?'Такой ник уже занят':'Не удалось изменить ник');return}closeModal();await syncOnline();toast('Ник изменён: '+oldNick+' → '+newNick)}

async function kickMemberByNick(nick){if(db.profile.access!=='admin'||!sb||!onlineMember)return;let {data:m,error:e}=await sb.from('members').select('id,nick').eq('squad_id',onlineMember.squad_id).eq('nick',nick).single();if(e||!m){toast('Участник не найден');return}if(!confirm('Выгнать '+nick+' из состава?'))return;let r=await sb.rpc('admin_kick_member',{p_member_id:m.id});if(r.error){toast('Не удалось выгнать');return}await syncOnline();toast(nick+' исключён')}
function changeInviteCode(){if(db.profile.access!=='admin')return;modal('<h2>Код вступления</h2><form class="form" onsubmit="saveInviteCode(event)"><span class="muted">Новый код для входа в состав FURY</span><input name="code" required minlength="4" placeholder="Новый код"><div class="dialogfoot"><button type="button" class="ghost" onclick="closeModal()">Отмена</button><button class="primary">Сохранить</button></div></form>')}
async function saveInviteCode(e){e.preventDefault();let code=new FormData(e.target).get('code').trim();let r=await sb.rpc('admin_change_invite_code',{p_new_code:code});if(r.error){toast('Не удалось сменить код');return}closeModal();toast('Код вступления изменён')}
function furySelectPicker(name,items,value='',placeholder='Выбрать'){let val=String(value??''),list=items.map(x=>typeof x==='object'?x:{value:String(x),label:String(x)}),cur=list.find(x=>String(x.value)===val),label=cur?cur.label:placeholder,opts=list.map(x=>{let v=String(x.value),l=String(x.label);return '<button type="button" class="fury-select-option'+(v===val?' active':'')+'" data-value="'+esc(v)+'" onclick="furyPickSelect(this)">'+esc(l)+'</button>'}).join('');return '<div class="fury-select"><input type="hidden" name="'+name+'" value="'+esc(val)+'"><button type="button" class="fury-select-trigger" onclick="furyToggleSelect(this,event)"><span>'+esc(label)+'</span><i></i></button><div class="fury-select-menu">'+opts+'</div></div>'}
function furyCloseSelectMenus(except){document.querySelectorAll('.fury-select.open').forEach(x=>{if(x!==except){x.classList.remove('open');let m=x.querySelector('.fury-select-menu');if(m)m.removeAttribute('style')}})}
function furyToggleSelect(btn,e){if(e)e.stopPropagation();let box=btn.closest('.fury-select'),willOpen=!box.classList.contains('open');furyCloseSelectMenus(box);furyCloseTimeMenus();box.classList.remove('drop-up');box.classList.toggle('open',willOpen);if(willOpen)setTimeout(()=>{let menu=box.querySelector('.fury-select-menu'),active=menu?.querySelector('.fury-select-option.active'),r=box.getBoundingClientRect(),gap=5,below=window.innerHeight-r.bottom-gap-8,above=r.top-gap-8,space=Math.max(120,Math.min(250,Math.max(below,above)));if(menu){menu.style.setProperty('position','fixed','important');menu.style.setProperty('left',r.left+'px','important');menu.style.setProperty('right','auto','important');menu.style.setProperty('width',r.width+'px','important');menu.style.setProperty('max-height',space+'px','important');if(below>=Math.min(250,menu.scrollHeight)||below>=above){menu.style.setProperty('top',(r.bottom+gap)+'px','important');menu.style.removeProperty('bottom')}else{menu.style.setProperty('top','auto','important');menu.style.setProperty('bottom',(window.innerHeight-r.top+gap)+'px','important')}if(active)menu.scrollTop=Math.max(0,active.offsetTop-(menu.clientHeight-active.offsetHeight)/2)}},0)}
function furyPickSelect(btn){let box=btn.closest('.fury-select'),v=btn.dataset.value;box.querySelector('input[type="hidden"]').value=v;box.querySelector('.fury-select-trigger span').textContent=btn.textContent;box.querySelectorAll('.fury-select-option').forEach(x=>x.classList.toggle('active',x===btn));box.classList.remove('open');box.querySelector('.fury-select-menu')?.removeAttribute('style')}
function quantityPicker(name,value=1){let items=Array.from({length:50},(_,i)=>({value:String(i+1),label:String(i+1)}));return furySelectPicker(name,items,value?String(Math.min(50,Math.max(1,Number(value)||1))):'','Количество (необязательно)')}
function newTask(){modal('<h2>Создать задачу</h2><form class="form" onsubmit="createTask(event)"><input name="title" required placeholder="Например: Собрать металл"><div class="formrow">'+quantityPicker('need')+furySelectPicker('unit',['Стак','Хомяк','Ящик'],'Стак','Единица')+'</div><div class="formrow"><div><small class="muted">Сделать до даты</small><input name="deadline_date" class="datepick" type="date" required onclick="if(this.showPicker)this.showPicker()" onfocus="if(this.showPicker)this.showPicker()"></div><div><small class="muted">До времени</small>'+timePicker('deadline','21:00')+'</div></div><input name="place" placeholder="Куда / место"><textarea name="comment" placeholder="Комментарий"></textarea><div class="dialogfoot"><button type="button" class="ghost" onclick="closeModal()">Отмена</button><button class="primary">Создать</button></div></form>')}
async function createTask(e){e.preventDefault();let f=new FormData(e.target),need=Number(f.get('need'))||null;if(!sb||!onlineMember)return;let row={squad_id:onlineMember.squad_id,creator_id:onlineMember.id,title:f.get('title'),quantity:need,unit:f.get('unit')||'шт.',place:f.get('place')||null,priority:f.get('priority')||'Обычный',deadline:(f.get('deadline_date')+' '+getPickedTime(f,'deadline')),comment:f.get('comment')||null,status:'В процессе'};let {error}=await sb.from('tasks').insert(row);if(error){toast('Не удалось создать задачу');return}closeModal();await syncOnline();go('Задачи')}
function cancelEditTask(id){taskDetails(id)}
function editTask(id){let t=db.tasks.find(x=>x.id===id);if(!t)return;let people=(db.members||[]).map(m=>m[0]),d=String(t.deadline||'').replace('T',' '),date=d.slice(0,10),time=(d.match(/(\d{2}:\d{2})/)||[])[1]||'21:00';modal('<h2>Редактировать задачу</h2><form class="form" onsubmit="saveTask(event,'+id+')"><input name="title" required value="'+esc(t.title)+'"><div class="formrow">'+quantityPicker('need',t.need||1)+furySelectPicker('unit',[{value:'',label:'Единица'},'Стак','Хомяк','Ящик'],t.unit==='шт.'?'':t.unit,'Единица')+'</div><div class="formrow"><div><small class="muted">Сделать до даты</small><input name="deadline_date" class="datepick" type="date" required value="'+esc(date)+'" onclick="if(this.showPicker)this.showPicker()"></div><div><small class="muted">До времени</small>'+timePicker('deadline',time)+'</div></div><input name="place" value="'+esc(t.place||'')+'" placeholder="Куда / место">'+furySelectPicker('owner',[{value:'',label:'Ответственный (необязательно)'},...people],t.owner||'','Ответственный (необязательно)')+'<textarea name="comment" placeholder="Комментарий">'+esc(t.comment||'')+'</textarea><div class="dialogfoot"><button type="button" class="ghost" onclick="cancelEditTask('+id+')">Отмена</button><button type="button" class="ghost" onclick="closeModal()">Закрыть</button><button class="primary">Сохранить</button></div></form>')}
async function saveTask(e,id){e.preventDefault();let f=new FormData(e.target),owner=String(f.get('owner')||''),assignee=null;if(owner){let m=(db.members||[]).find(x=>x[0]===owner);if(m){let r=await sb.from('members').select('id').eq('squad_id',onlineMember.squad_id).eq('nick',owner).maybeSingle();if(r.data)assignee=r.data.id}}let deadline=f.get('deadline_date')+' '+getPickedTime(f,'deadline');let r=await sb.rpc('update_task_details',{p_task_id:id,p_title:f.get('title'),p_quantity:Number(f.get('need'))||null,p_unit:f.get('unit')||'шт.',p_place:f.get('place')||'',p_deadline:deadline,p_comment:f.get('comment')||'',p_assignee_id:assignee});if(r.error){toast('Редактировать может создатель или админ');return}closeModal();await syncOnline();toast('Задача обновлена')}
async function joinTask(id){let r=await sb.rpc('claim_task',{p_task_id:id});if(r.error){toast('Не удалось взять задачу');return}await syncOnline();toast('Задача взята')}
async function addContribution(id){let q=Number(prompt('Сколько добавить?'));if(!q||q<1)return;let t=db.tasks.find(x=>x.id===id);let {error}=await sb.from('task_contributions').insert({task_id:id,member_id:onlineMember.id,amount:q});if(error){toast('Не удалось добавить вклад');return}if(t&&t.need&&Number(t.done||0)+q>=Number(t.need)&&t.status!=='Выполнена'){let r=await sb.rpc('set_task_status',{p_task_id:id,p_status:'Выполнено'});if(r.error){toast('Количество собрано, но статус не изменён автоматически')}}await syncOnline();if(t&&t.need&&Number(t.done||0)+q>=Number(t.need)){showTaskComplete()}else toast('Вклад добавлен')}
function historyTask(id){let t=db.tasks.find(x=>x.id===id);modal('<h2>История · '+esc(t.title)+'</h2><div class="list">'+(t.history.length?t.history.map(h=>'<div class="item itemtop"><span>'+esc(h.nick)+' · +'+h.qty+' '+esc(t.unit)+'</span><button class="ghost" onclick="undoContribution('+id+','+h.id+')">Отменить</button></div>').join(''):'<div class="empty">Вкладов пока нет</div>')+'</div><div class="dialogfoot"><button class="ghost" onclick="closeModal()">Закрыть</button></div>')}
async function undoContribution(id,cid){let t=db.tasks.find(x=>x.id===id),h=t?.history?.find(x=>x.id===cid),after=Math.max(0,Number(t?.done||0)-Number(h?.qty||0));let {error}=await sb.from('task_contributions').delete().eq('id',cid);if(error){toast('Нельзя отменить этот вклад');return}if(t&&t.need&&after<Number(t.need)&&(t.status==='Выполнено'||t.status==='Выполнена')){let r=await sb.rpc('set_task_status',{p_task_id:id,p_status:'В процессе'});if(r.error)toast('Количество уменьшено, но статус не изменён')}closeModal();await syncOnline();toast('Вклад отменён')}
async function toggleTask(id){let t=db.tasks.find(x=>x.id===id),status=t.status==='Выполнено'||t.status==='Выполнена'?'В процессе':'Выполнено';let r=await sb.rpc('set_task_status',{p_task_id:id,p_status:status});if(r.error){toast('Изменить статус может ответственный, создатель или админ');return}await syncOnline()}
async function deleteTask(id){let t=db.tasks.find(x=>x.id===id);if(!t)return;if(!confirm('Удалить эту задачу?'))return;let {error}=await sb.from('tasks').delete().eq('id',id);if(error){toast('Удалить может только создатель или админ');return}closeModal();await syncOnline();toast('Задача удалена')}
function newOp(){modal('<h2>План на рейд</h2><form class="form" onsubmit="createOp(event)"><input name="title" required placeholder="Название / цель"><input name="sector" placeholder="Сектор, например D3"><label class="photoupload"><span>Фото для рейда</span><input name="images" type="file" accept="image/*" multiple onchange="previewRaidPhotos(this)"><small class="muted">До 5 фото · максимум 5 МБ каждое</small></label><div id="raidPhotoPreview" class="raidphotopreview"></div><div class="formrow"><div><small class="muted">Дата</small><input name="raid_date" class="datepick" type="date" required onclick="if(this.showPicker)this.showPicker()" onfocus="if(this.showPicker)this.showPicker()"></div><div><small class="muted">Время</small>'+timePicker('time','20:00')+'</div></div><input name="walls" type="number" min="0" placeholder="Количество стен"><input name="loadout" placeholder="Что взять: С4, гранаты, медицина..."><input name="transport" placeholder="Транспорт"><input name="rally_point" placeholder="Точка сбора"><textarea name="note" placeholder="Подготовка / комментарий"></textarea><div class="dialogfoot"><button type="button" class="ghost" onclick="closeModal()">Отмена</button><button class="primary">Создать</button></div></form>')}
async function uploadRaidPhotos(input){let files=Array.from(input?.files||[]).slice(0,5),urls=[];for(let file of files){if(file.size>5242880)throw new Error('Фото больше 5 МБ');let ext=(file.name.split('.').pop()||'jpg').toLowerCase(),path=onlineMember.squad_id+'/'+Date.now()+'-'+Math.random().toString(36).slice(2)+'.'+ext;let r=await sb.storage.from('raid-photos').upload(path,file,{contentType:file.type||'image/jpeg'});if(r.error)throw r.error;urls.push(sb.storage.from('raid-photos').getPublicUrl(path).data.publicUrl)}return urls}
function previewRaidPhotos(input){let box=$('#raidPhotoPreview'),files=Array.from(input.files||[]).slice(0,5);if(box)box.innerHTML=files.map(f=>'<img src="'+URL.createObjectURL(f)+'" alt="Фото для рейда">').join('')}
async function createOp(e){e.preventDefault();let f=new FormData(e.target),btn=e.submitter;if(btn){btn.disabled=true;btn.textContent='Загрузка…'}let photos=[];try{photos=await uploadRaidPhotos(e.target.elements.images)}catch(x){if(btn){btn.disabled=false;btn.textContent='Создать'}toast(x.message||'Не удалось загрузить фото');return}let {error}=await sb.from('raids').insert({squad_id:onlineMember.squad_id,creator_id:onlineMember.id,title:f.get('title'),raid_time:getPickedTime(f,'time'),raid_date:f.get('raid_date'),sector:f.get('sector')||null,walls:Number(f.get('walls'))||null,loadout:f.get('loadout')||null,transport:f.get('transport')||null,rally_point:f.get('rally_point')||null,target_images:photos,note:f.get('note')||null});if(error){if(btn){btn.disabled=false;btn.textContent='Создать'}toast('Не удалось создать план');return}closeModal();await syncOnline();render()}
function cancelEditOp(id){viewOp(id)}
function editOp(id){let o=db.ops.find(x=>x.id===id);if(!o)return;modal('<h2>Редактировать план</h2><form class="form" onsubmit="saveOp(event,'+id+')"><input name="title" required value="'+esc(o.title)+'"><input name="sector" value="'+esc(o.sector||'')+'" placeholder="Сектор, например D3">'+((o.images&&o.images.length)?'<div><small class="muted">ФОТО ДЛЯ РЕЙДА</small><div class="raidphotopreview">'+o.images.map(u=>'<img src="'+esc(u)+'" alt="Фото для рейда">').join('')+'</div></div>':'')+'<label class="photoupload"><span>Добавить / заменить фото</span><input name="images" type="file" accept="image/*" multiple onchange="previewRaidPhotos(this)"><small class="muted">До 5 фото</small></label><div id="raidPhotoPreview" class="raidphotopreview"></div><div class="formrow"><div><small class="muted">Дата</small><input name="raid_date" class="datepick" type="date" required value="'+esc(o.date||'')+'" onclick="if(this.showPicker)this.showPicker()" onfocus="if(this.showPicker)this.showPicker()"></div><div><small class="muted">Время</small>'+timePicker('time',o.time||'20:00')+'</div></div><input name="walls" type="number" min="0" value="'+(o.walls||'')+'" placeholder="Количество стен"><input name="loadout" value="'+esc(o.loadout||'')+'" placeholder="Что взять"><input name="transport" value="'+esc(o.transport||'')+'" placeholder="Транспорт"><input name="rally_point" value="'+esc(o.rally_point||'')+'" placeholder="Точка сбора"><textarea name="note" placeholder="Подготовка / комментарий">'+esc(o.note)+'</textarea><div class="dialogfoot"><button type="button" class="ghost" onclick="cancelEditOp('+id+')">Отмена</button><button type="button" class="ghost" onclick="closeModal()">Закрыть</button><button class="primary">Сохранить</button></div></form>')}
async function saveOp(e,id){e.preventDefault();let f=new FormData(e.target),o=db.ops.find(x=>x.id===id),photos=Array.isArray(o?.images)?o.images:[];if(e.target.elements.images?.files?.length){try{photos=await uploadRaidPhotos(e.target.elements.images)}catch(x){toast('Не удалось загрузить фото');return}}let {error}=await sb.from('raids').update({title:f.get('title'),raid_date:f.get('raid_date'),raid_time:getPickedTime(f,'time'),sector:f.get('sector')||null,walls:Number(f.get('walls'))||null,loadout:f.get('loadout')||null,transport:f.get('transport')||null,rally_point:f.get('rally_point')||null,target_images:photos,note:f.get('note')||null}).eq('id',id);if(error){toast('Редактировать может создатель или админ');return}closeModal();await syncOnline();toast('Рейд обновлён')}
async function deleteOp(id){if(!confirm('Удалить этот рейд?'))return;let {error}=await sb.from('raids').delete().eq('id',id);if(error){toast('Удалить может создатель или админ');return}await syncOnline();toast('Рейд удалён')}
async function toggleRaid(id,keepOpen=false){let o=db.ops.find(x=>x.id===id),joined=(o.participants||[]).includes(db.profile.nick);let q=joined?sb.from('raid_participants').delete().eq('raid_id',id).eq('member_id',onlineMember.id):sb.from('raid_participants').insert({raid_id:id,member_id:onlineMember.id});let {error}=await q;if(error){toast('Не удалось изменить участие');return}await syncOnline();if(keepOpen)viewOp(id);toast(joined?'Ты вышел из рейда':'Ты записался на рейд')}
function raidPeople(o){let p=Array.isArray(o.participants)?o.participants:[];return p.length?p.map(n=>'<span class="badge work">'+esc(n)+'</span>').join(' '):'<span class="muted">Пока никто не записался</span>'}
async function setPresence(s){if(s==='Без меня')s='Не буду';let old={...db.presence};db.presence.status=s;if(s!=='Буду')db.presence.time='';save();updateHomePresenceUI();let row={squad_id:onlineMember.squad_id,member_id:onlineMember.id,day:moscowPresenceDay(),status:s,join_time:s==='Буду'?(db.presence.time||null):null,updated_at:new Date().toISOString()};let {error}=await sb.from('presence_history').upsert(row,{onConflict:'member_id,day'});if(error){db.presence=old;save();updateHomePresenceUI();toast('Ошибка синхронизации');return}window.furySilentSync=true;try{await syncOnline()}finally{window.furySilentSync=false}updateHomePresenceUI();if(s==='Буду')setTime()}function setTime(){modal('<h2>Время захода</h2><form class="form" onsubmit="saveTime(event)"><label class="muted">Выбери время</label>'+timePicker('time',db.presence.time||'20:00',10)+'<div class="dialogfoot"><button type="button" class="ghost" onclick="closeModal()">Отмена</button><button class="primary">Сохранить</button></div></form>','time-entry-dialog')}async function saveTime(e){e.preventDefault();let f=new FormData(e.target),t=getPickedTime(f,'time');db.presence.time=t;let status=db.presence.status==='Не буду'?'Буду':db.presence.status;let row={squad_id:onlineMember.squad_id,member_id:onlineMember.id,day:moscowPresenceDay(),status,join_time:t,updated_at:new Date().toISOString()};let {error}=await sb.from('presence_history').upsert(row,{onConflict:'member_id,day'});if(error){toast('Ошибка синхронизации');return}closeModal();window.furySilentSync=true;try{await syncOnline()}finally{window.furySilentSync=false}updateHomePresenceUI();toast('Время обновлено')}
function editProfile(){let admin=db.profile.access==='admin';modal('<h2>Профиль бойца</h2>'+(admin?'<div style="margin-bottom:12px"><span class="badge work">АДМИНИСТРАТОР FURY</span></div>':'')+'<form class="form" onsubmit="saveProfile(event)"><input name="nick" required value="'+esc(db.profile.nick)+'" placeholder="Ник"><select name="role">'+['Rifler','Bomber','Locker','Builder','Helper','Sniper'].map(r=>'<option '+(r===db.profile.role?'selected':'')+'>'+r+'</option>').join('')+'</select><div class="dialogfoot profile-actions"><button type="button" class="logoutbtn" onclick="logoutSquad()">ВЫЙТИ</button><span class="profile-actions-spacer" style="flex:1"></span><button type="button" class="ghost" onclick="closeModal()">Отмена</button><button class="primary">Сохранить</button></div></form>')}
