async function uploadPlaceFiles(kind,files){let commentEl=$('#placeComment');if(commentEl){placeDraft[kind]=placeDraft[kind]||{images:[],comment:''};placeDraft[kind].comment=commentEl.value}files=[...(files||[])].filter(f=>f&&f.type&&f.type.startsWith('image/'));if(!files.length){toast('В буфере нет изображения');return}let d=placeDraft[kind]||{images:[],comment:''},slots=5-d.images.length;if(slots<=0){toast('Максимум 5 фото');return}for(let file of files.slice(0,slots)){if(file.size>10*1024*1024){toast('Фото больше 10 МБ пропущено');continue}let ext=(file.name?.split('.').pop()||file.type.split('/')[1]||'png').replace(/[^a-zA-Z0-9]/g,'').toLowerCase(),path=onlineMember.squad_id+'/'+kind+'/'+Date.now()+'-'+Math.random().toString(36).slice(2,8)+'.'+ext;let up=await sb.storage.from('squad-photos').upload(path,file,{contentType:file.type,upsert:false});if(up.error){toast('Не удалось загрузить фото');continue}d.images.push(sb.storage.from('squad-photos').getPublicUrl(path).data.publicUrl)}placeDraft[kind]=d;refreshPlaceKind(kind)}
function removeDraftPlacePhoto(kind,i){let commentEl=$('#placeComment');if(commentEl){placeDraft[kind]=placeDraft[kind]||{images:[],comment:''};placeDraft[kind].comment=commentEl.value}let d=placeDraft[kind];if(!d)return;d.images.splice(i,1);refreshPlaceKind(kind)}
async function publishPlacePost(kind){let d=placeDraft[kind]||{images:[]},comment=$('#placeComment')?.value.trim()||'';if(!d.images.length&&!comment){toast('Добавь фото или комментарий');return}let {error}=await sb.from('squad_place_posts').insert({squad_id:onlineMember.squad_id,kind,images:d.images.slice(0,5),comment,created_by:onlineMember.id});if(error){toast('Не удалось опубликовать');return}placeDraft[kind]={images:[],comment:''};toast('Опубликовано');refreshPlaceKind(kind)}
async function editPlacePost(id,kind){document.querySelectorAll('.ref-post-menu-pop.open').forEach(x=>x.classList.remove('open'));let {data:p,error}=await sb.from('squad_place_posts').select('*').eq('id',id).single();if(error||!p){toast('Редактирование недоступно');return}placeEdit={id:p.id,kind,images:[...(p.images||[])],comment:p.comment||''};openPlaceEditModal()}
function cancelPlaceEdit(){placeEdit=null;closeModal()}
function openPlaceEditModal(){let p=placeEdit;if(!p)return;modal('<h2>Редактировать публикацию</h2><div class="raidphotos placephotos">'+p.images.map((u,i)=>'<div class="placephoto"><img src="'+esc(u)+'" onclick="openRaidPhoto(\''+esc(u)+'\')" style="cursor:zoom-in"><button class="place-photo-remove" onclick="removePlaceEditPhoto('+i+')">×</button></div>').join('')+'</div><input id="placeEditFiles" type="file" accept="image/*" multiple><div class="muted" style="margin:8px 0 14px">Можно добавить фото. Максимум 5.</div><textarea id="placeEditComment" class="place-comment" placeholder="Комментарий">'+esc(p.comment)+'</textarea><div class="dialogfoot"><button class="ghost" onclick="cancelPlaceEdit()">Отмена</button><button class="primary" onclick="savePlaceEdit()">Сохранить</button></div>');$('#placeEditFiles')?.addEventListener('change',e=>uploadPlaceEditFiles([...e.target.files]))}
function removePlaceEditPhoto(i){if(!placeEdit)return;placeEdit.comment=$('#placeEditComment')?.value??placeEdit.comment;placeEdit.images.splice(i,1);openPlaceEditModal()}
async function uploadPlaceEditFiles(files){if(!placeEdit)return;placeEdit.comment=$('#placeEditComment')?.value??placeEdit.comment;files=[...(files||[])].filter(f=>f?.type?.startsWith('image/')).slice(0,5-placeEdit.images.length);for(let file of files){if(file.size>10*1024*1024){toast('Фото больше 10 МБ пропущено');continue}let ext=(file.name?.split('.').pop()||file.type.split('/')[1]||'png').replace(/[^a-zA-Z0-9]/g,'').toLowerCase(),path=onlineMember.squad_id+'/'+placeEdit.kind+'/'+Date.now()+'-'+Math.random().toString(36).slice(2,8)+'.'+ext;let up=await sb.storage.from('squad-photos').upload(path,file,{contentType:file.type,upsert:false});if(up.error){toast('Не удалось загрузить фото');continue}placeEdit.images.push(sb.storage.from('squad-photos').getPublicUrl(path).data.publicUrl)}openPlaceEditModal()}
async function savePlaceEdit(){if(!placeEdit)return;placeEdit.comment=$('#placeEditComment')?.value.trim()||'';let {error}=await sb.from('squad_place_posts').update({images:placeEdit.images.slice(0,5),comment:placeEdit.comment}).eq('id',placeEdit.id);if(error){toast('Не удалось сохранить');return}let kind=placeEdit.kind;placeEdit=null;closeModal();toast('Публикация обновлена');refreshPlaceKind(kind)}
async function deletePlacePost(id,kind){if(!confirm('Удалить публикацию?'))return;let {error}=await sb.from('squad_place_posts').delete().eq('id',id);if(error){toast('Не удалось удалить');return}refreshPlaceKind(kind)}
function authScreen(){modal('<h2>Вход в FURY</h2><div id="authForm"></div>');showMemberLogin()}
function showMemberLogin(){let a=$('#authForm');if(!a)return;a.innerHTML='<form class="form" onsubmit="doJoin(event)"><input name="code" required placeholder="Код состава"><input name="nick" required value="" autocomplete="off" placeholder="Ник"><select name="role" required><option value="" selected disabled>Выбрать роль</option>'+['Rifler','Bomber','Locker','Builder','Helper','Sniper'].map(r=>'<option value="'+r+'">'+r+'</option>').join('')+'</select><button class="primary">ВОЙТИ В СОСТАВ</button></form>'}
function showAdminLogin(){let a=$('#authForm');if(!a)return;$('#adminTab')?.classList.add('on');$('#memberTab')?.classList.remove('on');a.innerHTML='<form class="form" onsubmit="adminLogin(event)"><input name="email" type="email" required autocomplete="username" placeholder="E-mail"><input name="password" type="password" required minlength="6" autocomplete="current-password" placeholder="Пароль"><button class="primary">ВОЙТИ КАК АДМИН</button><button type="button" class="ghost" onclick="adminSignup(event)">ПЕРВЫЙ ВХОД / СОЗДАТЬ ПАРОЛЬ</button><div id="adminAuthStatus" class="muted" style="min-height:18px"></div></form><small class="muted">При первом входе создай пароль. После этого используй обычный вход администратора.</small>'}
async function adminSignup(e){if(e)e.preventDefault();let st=$('#adminAuthStatus'),form=$('#authForm form');if(!form)return;let f=new FormData(form),email=String(f.get('email')||'').trim(),password=String(f.get('password')||'');if(!email){if(st)st.textContent='Введи e-mail';return}if(password.length<6){if(st)st.textContent='Пароль минимум 6 символов';return}if(st)st.textContent='Создаю учётную запись…';let r=await sb.auth.signUp({email,password});if(r.error){if(st)st.textContent='Ошибка: '+r.error.message;return}if(!r.data.session){if(st)st.textContent='Готово. Проверь почту и подтверди e-mail, затем нажми «ВОЙТИ КАК АДМИН».';return}if(st)st.textContent='Учётная запись создана. Вхожу…';await finishAdminLogin()}
async function adminLogin(e){e.preventDefault();let f=new FormData(e.target);await sb.auth.signOut({scope:'local'});let r=await sb.auth.signInWithPassword({email:f.get('email'),password:f.get('password')});if(r.error){toast('Неверный e-mail или пароль');return}await finishAdminLogin()}
async function finishAdminLogin(){let r=await sb.rpc('claim_admin_account');if(r.error){toast('Эта учётка не является администратором');await sb.auth.signOut({scope:'local'});return}onlineMember=r.data;db.profile={nick:r.data.nick,role:r.data.game_role,access:r.data.access_role};save();closeModal();await syncOnline();unlockApp();toast('Вход администратора выполнен')}
async function joinOnline(){if(!sb)return;let {data:{session}}=await sb.auth.getSession();if(session){let {data:m}=await sb.rpc('current_member');if(m){onlineMember=m;db.profile={nick:m.nick,role:m.game_role,access:m.access_role};save();await syncOnline();unlockApp();return}if(!session.user.is_anonymous&&session.user.email?.toLowerCase()==='nikitinrf@bk.ru'){await finishAdminLogin();return}}authScreen()}
async function ensureAnonymous(){let {data:{session}}=await sb.auth.getSession();if(!session||!session.user.is_anonymous){if(session)await sb.auth.signOut({scope:'local'});let r=await sb.auth.signInAnonymously();if(r.error)throw r.error}}
async function doJoin(e){e.preventDefault();let f=new FormData(e.target),nick=String(f.get('nick')||'').trim(),code=String(f.get('code')||'').trim();try{await ensureAnonymous()}catch(x){toast('Не удалось создать сессию');return}if(nick.toLowerCase()==='k1t0'){let r=await sb.rpc('join_admin_device',{p_code:code,p_nick:nick});if(r.error){toast('Неверный код администратора');return}onlineMember=r.data;db.profile={nick:r.data.nick,role:r.data.game_role,access:'admin'};save();closeModal();await syncOnline();unlockApp();toast('Вход администратора выполнен');return}let {data,error}=await sb.rpc('join_squad',{p_code:code,p_nick:nick,p_role:f.get('role')});if(error){toast(error.message.includes('duplicate')?'Ник уже занят':'Неверный код или ошибка входа');return}onlineMember=data;db.profile={nick:data.nick,role:data.game_role,access:data.access_role};save();closeModal();await syncOnline();unlockApp();toast('Добро пожаловать в FURY')}

function showK1t0Login(code){let a=$('#authForm');if(!a)return;a.innerHTML='<div class="form"><div class="muted">Профиль <b class="acid">k1t0</b></div><div class="muted">Вход без пароля через ссылку на почте.</div><button class="primary" onclick="sendK1t0MagicLink(\''+esc(code||'').replace(/'/g,"\\'")+'\')">ПОЛУЧИТЬ ССЫЛКУ НА ПОЧТУ</button><button type="button" class="ghost" onclick="showMemberLogin()">Назад</button><div id="k1t0AuthStatus" class="muted" style="min-height:18px"></div></div>'}
async function sendK1t0MagicLink(code){let st=$('#k1t0AuthStatus');if(st)st.textContent='Отправляю ссылку…';if(String(code||'').trim().toUpperCase()!=='FURYHUB'){if(st)st.textContent='Неверный код состава';return}await sb.auth.signOut({scope:'local'});let redirect=location.origin+location.pathname;let r=await sb.auth.signInWithOtp({email:'nikitinrf@bk.ru',options:{shouldCreateUser:false,emailRedirectTo:redirect}});if(r.error){if(st)st.textContent='Не удалось отправить ссылку';return}if(st)st.innerHTML='Ссылка отправлена на почту.<br>Открой письмо и нажми <b>Sign in</b>.'}

let syncTimer=null;function scheduleSync(){clearTimeout(syncTimer);syncTimer=setTimeout(()=>{if(onlineMember&&document.visibilityState==='visible'&&page!=='Взрыв')syncOnline()},700)}
function startSharedSync(){if(window.sharedSyncStarted)return;window.sharedSyncStarted=true;setInterval(async()=>{if(onlineMember&&document.visibilityState==='visible'&&page!=='Взрыв'){window.furySilentSync=true;try{await syncOnline();await refreshWallMetric()}finally{window.furySilentSync=false}}},30000);try{sb.channel('squad-shared').on('postgres_changes',{event:'*',schema:'public'},scheduleSync).subscribe();sb.channel('explosives-live').on('postgres_changes',{event:'UPDATE',schema:'public',table:'explosives_inventory'},async p=>{if(p.new?.squad_id!==onlineMember?.squad_id)return;updateExplosiveInput(p.new.item,p.new.quantity);await refreshWallMetric();if(page==='Главная'||page==='Сегодня')await renderRefExplosives()}).subscribe()}catch(e){console.warn(e)}}
function moscowPresenceDay(){let parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',hourCycle:'h23'}).formatToParts(new Date());let v=Object.fromEntries(parts.map(x=>[x.type,x.value]));let d=new Date(Date.UTC(+v.year,+v.month-1,+v.day));if(+v.hour<5)d.setUTCDate(d.getUTCDate()-1);return d.toISOString().slice(0,10)}
let protectCountdownTimer=null;
function protectClock(d){return d.toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'})}
function headerProtectHtml(){
 let p=db.protect,el=document.getElementById('headerProtect');if(!el)return;
 if(!p){el.className='ref-protect-head protect-red';el.innerHTML='<span class="ref-shield"></span><div><b>ПРОТЕКТ СПАЛ</b><small>Нет активного протекта</small></div><i></i>';return}
 let u=new Date(p.time),st=new Date(u.getTime()+3600000),en=new Date(st.getTime()+8*3600000),n=new Date(),cls=n<st?'protect-orange':n<en?'protect-green':'protect-red',label=n<st?'ПРОТЕКТ ЗАПУСКАЕТСЯ':n<en?'ПРОТЕКТ АКТИВЕН':'ПРОТЕКТ СПАЛ';
 el.className='ref-protect-head '+cls;
 let timer='';if(n<st){let ms=st-n,h=Math.floor(ms/3600000),m=Math.floor(ms%3600000/60000),s=Math.floor(ms%60000/1000);timer='<em class="ref-protect-countdown" data-start="'+st.toISOString()+'">До начала: '+String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')+'</em>'}
 el.innerHTML='<span class="ref-shield"></span><div><b>'+label+'</b><small>'+esc(p.nick)+' · '+protectClock(u)+' &nbsp; Начало: '+protectClock(st)+' · Спадёт: '+protectClock(en)+'</small>'+timer+'</div><i></i>';
 if(n<st)setTimeout(startHeaderProtectCountdown,0);
}
function sidebarProtectHtml(){
 let p=db.protect,el=document.getElementById('sidebarProtect');if(!el)return;
 if(!p){el.className='sidebar-protect protect-red';el.innerHTML='<small>ПРОТЕКТ</small><b>ПРОТЕКТ СПАЛ</b><span>Нет активного протекта</span>';return}
 let u=new Date(p.time),st=new Date(u.getTime()+3600000),en=new Date(st.getTime()+8*3600000),n=new Date(),cls=n<st?'protect-orange':n<en?'protect-green':'protect-red',label=n<st?'ЗАПУСКАЕТСЯ':n<en?'АКТИВЕН':'СПАЛ';
 let extra=n<st?'<em class="sidebar-protect-countdown" data-start="'+st.toISOString()+'">До начала: '+String(Math.floor((st-n)/3600000)).padStart(2,'0')+':'+String(Math.floor((st-n)%3600000/60000)).padStart(2,'0')+':'+String(Math.floor((st-n)%60000/1000)).padStart(2,'0')+'</em>':'';
 el.className='sidebar-protect '+cls;el.innerHTML='<small>ПРОТЕКТ</small><b>'+label+'</b><span class="sidebar-protect-who">'+esc(p.nick)+' · '+protectClock(u)+'</span><div class="sidebar-protect-times"><span>Начало: <strong>'+protectClock(st)+'</strong></span><span>Спадёт: <strong>'+protectClock(en)+'</strong></span></div>'+extra;if(n<st)setTimeout(startSidebarProtectCountdown,0);
}
function startSidebarProtectCountdown(){
 if(window.sidebarProtectCountdownTimer)clearInterval(window.sidebarProtectCountdownTimer);
 window.sidebarProtectCountdownTimer=setInterval(()=>{let el=document.querySelector('.sidebar-protect-countdown[data-start]');if(!el){clearInterval(window.sidebarProtectCountdownTimer);return}let ms=new Date(el.dataset.start)-new Date();if(ms<=0){clearInterval(window.sidebarProtectCountdownTimer);sidebarProtectHtml();return}let h=Math.floor(ms/3600000),m=Math.floor(ms%3600000/60000),s=Math.floor(ms%60000/1000);el.textContent='До начала: '+String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')},1000)
}
function startHeaderProtectCountdown(){
 let x=document.querySelector('.ref-protect-countdown[data-start]');if(!x)return;
 if(window.headerProtectCountdownTimer)clearInterval(window.headerProtectCountdownTimer);
 window.headerProtectCountdownTimer=setInterval(()=>{let el=document.querySelector('.ref-protect-countdown[data-start]');if(!el){clearInterval(window.headerProtectCountdownTimer);return}let ms=new Date(el.dataset.start)-new Date();if(ms<=0){clearInterval(window.headerProtectCountdownTimer);headerProtectHtml();return}let h=Math.floor(ms/3600000),m=Math.floor(ms%3600000/60000),s=Math.floor(ms%60000/1000);el.textContent='До начала: '+String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')},1000)
}
function protectHomeHtml(p){
 let updated=new Date(p.time),starts=new Date(updated.getTime()+60*60*1000),ends=new Date(starts.getTime()+8*60*60*1000),now=new Date(),status='';
 if(now<starts){let ms=starts-now,h=Math.floor(ms/3600000),m=Math.floor(ms%3600000/60000),s=Math.floor(ms%60000/1000);status='<div class="protect-countdown" data-start="'+starts.toISOString()+'">До начала: <b>'+String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')+'</b></div>'}
 else if(now<ends){status='<div class="protect-active">ПРОТЕКТ АКТИВЕН</div>'}
 else{status='<div class="protect-ended">ПРОТЕКТ СПАЛ</div>'}
 setTimeout(startProtectCountdown,0);
 return '<div class="protect-who"><b>'+esc(p.nick)+'</b> · '+protectClock(updated)+'</div><div class="protect-times">Начало: <b>'+protectClock(starts)+'</b> · Спадёт: <b>'+protectClock(ends)+'</b></div>'+status;
}
function startProtectCountdown(){
 clearInterval(protectCountdownTimer);
 let el=document.querySelector('.protect-countdown[data-start]');if(!el)return;
 protectCountdownTimer=setInterval(()=>{let x=document.querySelector('.protect-countdown[data-start]');if(!x){clearInterval(protectCountdownTimer);return}let end=new Date(x.dataset.start),ms=end-new Date();if(ms<=0){clearInterval(protectCountdownTimer);if(page==='Главная')render();return}let h=Math.floor(ms/3600000),m=Math.floor(ms%3600000/60000),s=Math.floor(ms%60000/1000);x.innerHTML='До начала: <b>'+String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')+'</b>'},1000);
}
function confirmQuickProtect(){if(!confirm('Обновить протект?'))return;quickProtect()}
async function quickProtect(){
 if(!onlineMember){toast('Профиль не найден');return}
 let {error}=await sb.from('protect_updates').insert({squad_id:onlineMember.squad_id,member_id:onlineMember.id});
 if(error){toast('Не удалось обновить протект');return}
 await syncOnline();toast('Протект обновлён')
}
function protectFormatDate(iso){return new Date(iso).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}
function protectMoscowParts(iso){let parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(iso));let p=Object.fromEntries(parts.map(x=>[x.type,x.value]));return{date:p.year+'-'+p.month+'-'+p.day,time:p.hour+':'+p.minute}}
async function showProtectHistory(){
 let hs=db.protectHistory||[],edits=[];
 if(onlineMember){let res=await sb.from('protect_update_edits').select('*').eq('squad_id',onlineMember.squad_id).order('edited_at',{ascending:false});if(res.error){console.warn('Protect edit history:',res.error);toast('Не удалось загрузить историю изменений')}else edits=res.data||[]}
 let names=Object.fromEntries((db.members||[]).map(x=>[x[0],x[0]])),members=db.protectMemberNames||{};
 let rows=hs.length?hs.map(x=>{
  let changes=edits.filter(y=>String(y.protect_update_id)===String(x.id));
  let details=changes.length?'<div class="protect-edit-log">'+changes.map(y=>'<div class="muted">Изменил: <b>'+esc(members[y.edited_by]||'Участник')+'</b> · '+protectFormatDate(y.edited_at)+'<div>'+protectFormatDate(y.old_effective_at)+' → '+protectFormatDate(y.new_effective_at)+'</div></div>').join('')+'</div>':'';
  let corrected=x.time!==x.pressedAt;
  return '<div class="item protect-history-item"><div class="protect-history-info"><b>'+esc(x.nick)+'</b><div class="muted">Время выхода: '+protectFormatDate(x.time)+'</div>'+(corrected?'<div class="muted">Нажатие: '+protectFormatDate(x.pressedAt)+'</div>':'')+details+'</div><div class="protect-history-actions"><button type="button" class="ghost" onclick="editProtectTime('+Number(x.id)+')">Изменить время</button><button type="button" class="danger protect-delete-btn" onclick="deleteProtectAt('+Number(x.id)+')">Удалить</button></div></div>'
 }).join(''):'<div class="empty">История пока пустая</div>';
 modal('<h2>Управление протектом</h2><p class="muted">Время выхода можно исправить. Начало защиты — через 1 час после выхода.</p><div class="list protect-history-list">'+rows+'</div><div class="modalactions"><button class="protect-close-btn" onclick="closeModal()">Закрыть</button></div>')
}
function editProtectTime(id){
 let x=(db.protectHistory||[]).find(y=>Number(y.id)===Number(id));if(!x){toast('Отметка не найдена');return}
 let p=protectMoscowParts(x.time);
 modal('<h2>Изменить время протекта</h2><p class="muted">Нажал: '+esc(x.nick)+' · '+protectFormatDate(x.pressedAt)+'</p><form class="form" onsubmit="saveProtectTime(event,'+Number(x.id)+')"><label class="muted">Фактическое время выхода из игры (МСК)</label><input class="datepick" type="date" name="protect_date" value="'+esc(p.date)+'" required>'+timePicker('protect_time',p.time)+'<div class="dialogfoot"><button type="button" class="ghost" onclick="showProtectHistory()">Отмена</button><button class="primary">Сохранить</button></div></form>')
}
async function saveProtectTime(e,id){
 e.preventDefault();if(!onlineMember)return;
 let f=new FormData(e.target),date=String(f.get('protect_date')||''),time=getPickedTime(f,'protect_time');
 if(!/^\d{4}-\d{2}-\d{2}$/.test(date)){toast('Выбери дату');return}
 let ms=Date.parse(date+'T'+time+':00+03:00');
 if(!Number.isFinite(ms)||ms>Date.now()){toast('Время выхода не может быть в будущем');return}
 let button=e.target.querySelector('button.primary');if(button)button.disabled=true;
 let {data,error}=await sb.from('protect_updates').update({effective_at:new Date(ms).toISOString()}).eq('squad_id',onlineMember.squad_id).eq('id',id).select('id').single();
 if(error||!data){toast('Не удалось изменить время протекта');if(button)button.disabled=false;return}
 await syncOnline();await showProtectHistory();toast('Время протекта изменено')
}
async function deleteProtectAt(id){
 if(!confirm('Удалить эту отметку об обновлении протекта?'))return;
 let {error}=await sb.from('protect_updates').delete().eq('squad_id',onlineMember.squad_id).eq('id',id);
 if(error){toast('Не удалось удалить');return}
 await syncOnline();await showProtectHistory();toast('Отметка удалена')
}
function protect(){let opts=(db.members||[]).map(m=>'<option value="'+esc(m[0])+'">'+esc(m[0])+'</option>').join('');let last=db.protect?('<div class="item"><div class="muted">ПОСЛЕДНЕЕ ОБНОВЛЕНИЕ</div><h3>'+esc(db.protect.nick)+'</h3><div>'+new Date(db.protect.time).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})+'</div><div class="actions"><button class="danger" onclick="deleteProtect()">Удалить</button></div></div>'):'<div class="empty">Протект ещё не обновляли</div>';$('#view').innerHTML='<div class="card"><h2>Протект</h2><p class="muted">Выберите участника, который обновил протект.</p><form class="protectquick" onsubmit="saveProtect(event)"><select name="nick" required>'+opts+'</select><button class="primary protectbtn">ОБНОВИЛ ПРОТЕКТ</button></form><div style="margin-top:18px">'+last+'</div></div>'}
async function deleteProtect(){if(!db.protect)return;if(!confirm('Удалить отметку об обновлении протекта?'))return;let {error}=await sb.from('protect_updates').delete().eq('squad_id',onlineMember.squad_id).eq('id',db.protect.id);if(error){toast('Не удалось удалить');return}await syncOnline();toast('Отметка удалена')}
async function saveProtect(e){e.preventDefault();let f=new FormData(e.target),nick=f.get('nick'),res=await sb.from('members').select('id').eq('squad_id',onlineMember.squad_id).eq('nick',nick).single(),member=res.data;if(!member){toast('Участник не найден');return}let {error}=await sb.from('protect_updates').insert({squad_id:onlineMember.squad_id,member_id:member.id});if(error){toast('Не удалось обновить протект');return}await syncOnline();toast('Протект обновлён')}
async function syncOnline(){if(!sb||!onlineMember)return;let day=moscowPresenceDay();let [mr,pr,tr,cr,rr,rpr,por]=await Promise.all([
sb.from('members').select('*').order('joined_at'),
sb.from('presence_history').select('*').eq('day',day),
sb.from('tasks').select('*').eq('squad_id',onlineMember.squad_id).order('created_at',{ascending:false}),
sb.from('task_contributions').select('*').order('created_at'),
sb.from('raids').select('*').eq('squad_id',onlineMember.squad_id).order('created_at',{ascending:false}),
sb.from('raid_participants').select('*'),
sb.from('protect_updates').select('*').eq('squad_id',onlineMember.squad_id).order('updated_at',{ascending:false})
]);if(mr.error||pr.error||tr.error||cr.error||rr.error||rpr.error||por.error){toast('Ошибка синхронизации');return}let ms=mr.data||[],ph=pr.data||[],nameById=Object.fromEntries(ms.map(m=>[m.id,m.nick]));db.members=ms.map(m=>{let p=ph.find(x=>x.member_id===m.id);return[m.nick,m.game_role,p?.join_time?.slice(0,5)||'',p?.status||'Не буду']});db.tasks=(tr.data||[]).map(t=>{let hs=(cr.data||[]).filter(c=>c.task_id===t.id).map(c=>({id:c.id,nick:nameById[c.member_id]||'Боец',qty:c.amount}));let done=hs.reduce((n,h)=>n+h.qty,0);return{id:t.id,title:t.title,need:t.quantity||0,done,unit:t.unit||'шт.',place:t.place||'',priority:t.priority,deadline:t.deadline||'',owner:nameById[t.assignee_id]||'',comment:t.comment||'',status:t.status,creator:nameById[t.creator_id]||'',history:hs}});db.ops=(rr.data||[]).map(r=>({id:r.id,title:r.title,date:r.raid_date||'',time:r.raid_time?.slice(0,5)||'20:00',note:r.note||'',sector:r.sector||'',walls:r.walls||0,loadout:r.loadout||'',transport:r.transport||'',rally_point:r.rally_point||'',images:r.target_images||[],creator:nameById[r.creator_id]||'',participants:(rpr.data||[]).filter(x=>x.raid_id===r.id).map(x=>nameById[x.member_id]).filter(Boolean)})).sort((a,b)=>{let av=a.date?(a.date+'T'+(a.time||'00:00')):'9999-12-31T23:59',bv=b.date?(b.date+'T'+(b.time||'00:00')):'9999-12-31T23:59';return av.localeCompare(bv)});db.protectHistory=(por.data||[]).map(x=>({id:x.id,member_id:x.member_id,nick:nameById[x.member_id]||'—',pressedAt:x.updated_at,time:x.effective_at||x.updated_at}));db.protect=db.protectHistory[0]||null;db.protectMemberNames=nameById;let me=ms.find(x=>x.id===onlineMember.id);if(me){onlineMember=me;db.profile={nick:me.nick,role:me.game_role,access:me.access_role};let mp=$('#mobileProfileNick');if(mp)mp.textContent=me.nick}let p=ph.find(x=>x.member_id===onlineMember.id);db.presence=p?{status:p.status,time:p.join_time?.slice(0,5)||''}:{status:'Не буду',time:''};save();if(!window.furySilentSync)render();startSharedSync();if(localStorage.getItem('fury_push_requested')==='yes')furySyncSubscription().catch(console.error)}
async function bootOnline(){try{sb=supabase.createClient(SUPA_URL,SUPA_KEY);await joinOnline()}catch(e){console.error(e);toast('Supabase недоступен')}}


document.addEventListener('paste',async e=>{if(page!=='Главная'&&page!=='Сегодня'&&page!=='Схрон'&&page!=='Базы')return;let files=[...(e.clipboardData?.items||[])].filter(x=>x.kind==='file'&&x.type.startsWith('image/')).map(x=>x.getAsFile()).filter(Boolean);if(!files.length)return;e.preventDefault();if(placeEdit){await uploadPlaceEditFiles(files)}else{await uploadPlaceFiles((page==='Главная'||page==='Сегодня')?'home':page==='Схрон'?'stash':'base',files)}});

function stashLifeHtml(p){
 const checked=p.stash_checked_at||p.created_at;
 const elapsed=Date.now()-new Date(checked).getTime();
 const left=Math.max(0,Math.ceil((14*86400000-elapsed)/86400000));
 const expired=elapsed>=14*86400000;
 const time=new Date(checked).toLocaleString('ru-RU',{timeZone:'Europe/Moscow'});
 const nick=esc(p.stash_checked_by_nick||p.author_nick||'Участник');
 return '<div style="margin-top:10px;display:flex;flex-wrap:wrap;align-items:center;gap:9px"><span style="font-size:12px;color:'+(expired?'#ef6464':left<=2?'#e8ad55':'#9ca8a2')+'">'+(expired?'Срок хранения истёк': 'До истечения: '+left+' дн.')+'</span><span class="muted" style="font-size:12px">Проверил: '+nick+' · '+time+' МСК</span><button class="ghost" style="font-size:12px;padding:7px 10px" onclick="refreshStash('+p.id+',this)">Обновить схрон</button></div>';
}
async function refreshStash(id,button){
 if(!sb||!onlineMember)return;
 if(button){button.disabled=true;button.textContent='Обновление…'}
 try{
 const {error}=await sb.rpc('refresh_stash',{p_post_id:id});
 if(error)throw error;
 toast('Схрон обновлён на 14 дней');
 await placePage('stash');
 }catch(e){console.error('refreshStash',e);toast('Ошибка обновления схрона');if(button){button.disabled=false;button.textContent='Обновить схрон'}}
}
function togglePlacePostMenu(id,e){if(e)e.stopPropagation();document.querySelectorAll('.ref-post-menu-pop.open').forEach(x=>{if(x.id!=='placePostMenu'+id)x.classList.remove('open')});document.getElementById('placePostMenu'+id)?.classList.toggle('open')}
document.addEventListener('click',e=>{if(!e.target.closest('.ref-post-menu'))document.querySelectorAll('.ref-post-menu-pop.open').forEach(x=>x.classList.remove('open'))});
document.addEventListener('click',e=>{if(!e.target.closest('.timefield'))furyCloseTimeMenus();if(!e.target.closest('.fury-select'))furyCloseSelectMenus()});

const furyNoticeCategories=[['protect','Протект','За час, за 15 минут и при окончании'],['protect_updated','Обновление протекта','Когда другой участник обновил протект'],['stash','Схрон','Новые записи, фотографии и комментарии'],['base','Базы','Новые записи, фотографии и комментарии'],['tasks','Задачи','Новые задачи'],['raids','Рейды','Новые планы рейдов'],['presence','Моё участие','Каждый день в 15:00 МСК'],['alarm','Экстренная тревога','Уведомление «НАС РЕЙДЯТ»']];
function furyNoticeEnabled(k){return localStorage.getItem('fury_notice_'+k)!=='off'}
function furyNoticeToggle(k,on){localStorage.setItem('fury_notice_'+k,on?'on':'off');furySyncSubscription().catch(console.error);settingsPage()}
const FURY_VAPID_PUBLIC='BMqTv-h0JU-rtMtn4VdaQpe7CBuOeyoW2EQAc8pdu439DqZs8A6pa_Og1mF8vOKy-WzThR9iHsz3Naw0fxrZe4k';
function furyPushKey(base64){const p='='.repeat((4-base64.length%4)%4);const raw=atob((base64+p).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,c=>c.charCodeAt(0))}
async function furyPushRequest(body){
 if(!sb||!onlineMember)throw Error('Сначала войдите в отряд');
 const {data:{session}}=await sb.auth.getSession();
 if(!session?.access_token)throw Error('Нет активной сессии');
 const r=await fetch(SUPA_URL+'/functions/v1/fury-push-register',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+session.access_token},body:JSON.stringify({...body,member_id:onlineMember.id})});
 if(!r.ok){let details={};try{details=await r.json()}catch(e){}throw Error(details.error||'Ошибка сервера ('+r.status+')')}
 return r.json();
}
async function furySyncSubscription(){
 if(localStorage.getItem('fury_push_requested')!=='yes'||!('serviceWorker' in navigator)||!onlineMember)return;
 const reg=await navigator.serviceWorker.register('./sw.js');
 const sub=await reg.pushManager.getSubscription();
 if(sub)await furyPushRequest({action:'subscribe',subscription:sub.toJSON(),preferences:Object.fromEntries(furyNoticeCategories.map(([k])=>[k,furyNoticeEnabled(k)]))});
}
function settingsPage(){
 const supported=('Notification' in window)&&('serviceWorker' in navigator)&&window.isSecureContext&&('PushManager' in window);
 const granted=supported&&Notification.permission==='granted';
 const installed=window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
 const requested=localStorage.getItem('fury_push_requested')==='yes';
 $('#view').innerHTML='<div class="card fury-settings"><div class="toolbar"><div><h2>Настройки</h2><span class="muted">Уведомления и параметры этого устройства.</span></div></div><div class="settings-row"><div><b>Пуш-уведомления</b><p class="muted">Получать сообщения, даже когда сайт закрыт</p></div><button class="ghost" onclick="togglePushPreference()">'+(requested?'ВЫКЛЮЧИТЬ':'ВКЛЮЧИТЬ')+'</button></div><div class="muted">Статус: '+(!supported?'не поддерживается браузером':!granted?'нет разрешения':requested?'включены на этом устройстве':'выключены')+'</div><h3 style="margin:24px 0 12px">КАТЕГОРИИ УВЕДОМЛЕНИЙ</h3>'+furyNoticeCategories.map(([key,name,desc])=>'<label class="settings-row fury-notice-row"><span><b>'+name+'</b><p class="muted">'+desc+'</p></span><input type="checkbox" '+(furyNoticeEnabled(key)?'checked':'')+' onchange="furyNoticeToggle(\''+key+'\',this.checked)"></label>').join('')+'</div>';
}
async function togglePushPreference(){
 if(!('Notification' in window)||!('serviceWorker' in navigator)||!('PushManager' in window)||!window.isSecureContext){toast('Откройте установленный сайт на поддерживаемом устройстве');return}
 try{
  const reg=await navigator.serviceWorker.register('./sw.js');
  if(localStorage.getItem('fury_push_requested')==='yes'){
   const sub=await reg.pushManager.getSubscription();
   if(sub){await furyPushRequest({action:'unsubscribe',endpoint:sub.endpoint});await sub.unsubscribe()}
   localStorage.setItem('fury_push_requested','no');toast('Уведомления выключены');
  }else{
   const permission=await Notification.requestPermission();
   if(permission!=='granted'){toast('Разрешение не предоставлено');settingsPage();return}
   let sub=await reg.pushManager.getSubscription();
   if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:furyPushKey(FURY_VAPID_PUBLIC)});
   await furyPushRequest({action:'subscribe',subscription:sub.toJSON(),preferences:Object.fromEntries(furyNoticeCategories.map(([k])=>[k,furyNoticeEnabled(k)]))});
   localStorage.setItem('fury_push_requested','yes');toast('Уведомления включены');
  }
 }catch(e){console.error(e);toast('Не удалось подключить: '+String(e.message||e).slice(0,70))}
 settingsPage();
}

